  "撤销 {0}": "{0} widerrufen",
  "停止此连接的后续访问，已归档资料保留。再次接入需要生成新配置。": "Künftige Zugriffe über diese Verbindung stoppen. Archivierte Materialien bleiben erhalten. Zum erneuten Verbinden ist eine neue Konfiguration nötig.",
