  "此设备或记录没有上报媒体状态，无法判断当时是否有音频播放。": "Dieses Gerät oder diese Aufzeichnung hat keinen Medienstatus gemeldet; die Audiowiedergabe zu diesem Zeitpunkt ist unbekannt.",
  "媒体采集已关闭": "Medienerfassung deaktiviert",
  "当时没有启用媒体采集，无法判断是否有音频播放。": "Medienerfassung war deaktiviert; die Audiowiedergabe zu diesem Zeitpunkt ist unbekannt.",
  "媒体采集等待授权": "Medienerfassung wartet auf Autorisierung",
  "请在 Android 客户端开启媒体采集，并在系统设置授权通知使用权，以读取应用公开的媒体会话。": "Aktivieren Sie die Medienerfassung auf Android und gewähren Sie Benachrichtigungszugriff in den Systemeinstellungen, um öffentliche Mediensitzungen zu lesen.",
  "媒体状态不可用": "Medienstatus nicht verfügbar",
  "系统当时未能提供媒体状态，不能据此认定没有音频播放。": "Das System konnte keinen Medienstatus liefern; dies belegt nicht, dass kein Audio abgespielt wurde.",
  "未观察到媒体会话": "Keine Mediensitzungen beobachtet",
  "这次观察没有发现可见的媒体会话；未公开媒体会话的应用可能无法被记录。": "Bei dieser Beobachtung wurden keine sichtbaren Mediensitzungen gefunden. Apps, die keine Mediensitzungen veröffentlichen, werden möglicherweise nicht aufgezeichnet.",
  " · {0} 个会话": " · {0} Sitzungen",
  "正在播放{0}": "Wiedergabe{0}",
  "{0} 个媒体会话": "Mediensitzungen: {0}",
  "应用通过系统公开的媒体状态；播放状态不代表你实际收听或专注。": "Von der App veröffentlichter Medienstatus belegt weder tatsächliches Hören noch Aufmerksamkeit.",
  "应用通过系统公开的媒体状态，不包含音频录制或语音转写。播放时长只累计已观察到的播放区间；暂停、未授权和采样空隙不会补齐，也不能据此确定你实际收听。": "Von der App veröffentlichter Medienstatus umfasst keine Audioaufnahme oder -transkription. Die Dauer zählt nur beobachtete Wiedergabeintervalle; Pausen, fehlende Berechtigung und Sampling-Lücken werden nicht aufgefüllt. Sie beweist kein tatsächliches Hören.",
  "{0}须为有效的 JSON 对象。": "{0} muss ein gültiges JSON-Objekt sein.",
  "{0}须为 JSON 对象，不能是数组或空值。": "{0} muss ein JSON-Objekt sein, kein Array oder null.",
  "模型服务地址须为完整的 HTTP(S) 地址。": "Die Modell-Dienst-URL muss eine vollständige HTTP(S)-URL sein.",
  "模型服务地址不能含凭据、查询参数或片段。": "Die Modell-URL darf keine Anmeldedaten, Abfrageparameter oder Fragmente enthalten.",
  "远程模型服务须使用 HTTPS；本机回环地址可使用 HTTP。": "Remote-Modelle erfordern HTTPS; Loopback-Dienste dürfen HTTP verwenden.",
