  "本机待同步记录存在损坏记录；原数据已保留，不能覆盖。": "Ausstehende lokale Kurznotizen enthalten beschädigte Aufzeichnungen. Originale bleiben erhalten; Überschreiben ist blockiert.",
  "记录 ID 已用于另一条内容。": "Diese Kurznotiz-ID wird bereits von anderem Inhalt verwendet.",
