  "保存结果待核实，请查看系统日历后重试": "Speichergebnis muss verifiziert werden. Prüfen Sie den Systemkalender und versuchen Sie es erneut.",
  "保存结果待核实。请检查日历权限与网络后再次核实；不会重复插入。": "Speichergebnis muss verifiziert werden. Prüfen Sie Kalenderzugriff und Verbindung und verifizieren Sie erneut. Es wird kein Duplikat eingefügt.",
