  "正在结束上一轮采集，请稍后再试": "Vorherige Erfassung wird abgeschlossen. Gleich erneut versuchen.",
  "此 MVP 只支持 macOS 采集；Windows/Linux 需要接入可靠前台应用识别后才可启用": "Dieses MVP unterstützt nur die Erfassung unter macOS. Windows/Linux erfordern eine zuverlässige Erkennung der Vordergrund-App.",
  "已开启；按应用级别记录，完整内容先经过本地隐私过滤": "Aktiviert; folgt den App-Erfassungsstufen mit lokaler Datenschutzfilterung für vollständige Inhalte",
  "采集已停止；本地记录保留，同步按设置独立运行": "Erfassung gestoppt. Lokale Aufzeichnungen bleiben erhalten; die Synchronisierung läuft unabhängig gemäß den Einstellungen.",
  "锁屏或休眠中，暂停采集": "Gesperrt oder im Ruhezustand; Erfassung pausiert",
  "已达到空闲阈值，暂停采集；操作电脑后恢复": "Leerlaufschwelle erreicht; die Erfassung wird fortgesetzt, sobald Sie den Computer verwenden",
