  "仅记录应用活动；未采集屏幕、窗口标题或正文": "Nur App-Aktivität; kein Bildschirm, Fenstertitel oder Text erfasst",
  "完整内容需要屏幕录制授权；仅活动应用仍可采样。请打开系统权限设置": "Vollständige Inhalte erfordern die Berechtigung zur Bildschirmaufzeichnung. Nur-Aktivitäts-Sampling bleibt verfügbar. Öffnen Sie die Systemberechtigungen.",
  "无法获取主屏截图，本次采集已跳过": "Hauptbildschirm kann nicht erfasst werden; Sample übersprungen",
  "截图超出单张大小限制，本次采集已跳过": "Screenshot überschreitet das Größenlimit; übersprungen",
  "采集失败，已跳过本次记录": "Erfassung fehlgeschlagen; Aufzeichnung übersprungen",
  "本地队列仍绑定原节点，请恢复已确认的连接": "Lokale Warteschlange ist noch an den ursprünglichen Knoten gebunden. Stellen Sie die bestätigte Verbindung wieder her.",
  "中央已删除此记录，不会重新创建；本机副本保留待处理。": "Zentrale Aufzeichnung wurde gelöscht und wird nicht neu erstellt. Lokale Kopie bleibt zur Prüfung erhalten.",
