  "无法读取配置或持久队列": "Konfiguration oder persistente Warteschlange kann nicht gelesen werden",
  "{0}\n如使用外接磁盘，请连接原磁盘后重试。应用不会创建空队列替代原目录。": "{0}\nSchließen Sie bei Verwendung einer externen Festplatte die ursprüngliche Festplatte an und versuchen Sie es erneut. Die App ersetzt das ursprüngliche Verzeichnis nicht durch eine leere Warteschlange.",
  "退出": "Beenden",
  "本地 macOS 助手不可用": "Lokaler macOS-Helfer nicht verfügbar",
  "本地 macOS 助手执行失败，本次采集已跳过": "Lokaler macOS-Helfer fehlgeschlagen; Erfassung übersprungen",
  "本地 macOS 助手返回值无效": "Lokaler macOS-Helfer hat ein ungültiges Ergebnis zurückgegeben",
  "无法读取应用列表": "App-Liste kann nicht gelesen werden",
  "无法确认屏幕应用身份，本次采集已跳过": "Bildschirm-Apps können nicht identifiziert werden; Erfassung übersprungen",
