  "二维码图片不能超过 8 MiB": "QR-Bild darf 8 MiB nicht überschreiten",
  "未找到唯一有效二维码，请选择清晰的单个连接二维码，或导入 JSON": "Kein eindeutiger gültiger QR-Code gefunden. Wählen Sie einen klaren einzelnen Einladungs-QR-Code oder importieren Sie JSON.",
  "无法确认前台应用身份，本次记录已跳过": "Vordergrund-App kann nicht identifiziert werden; Aufzeichnung übersprungen",
  "记录草稿格式无效": "Ungültiger Kurznotizentwurf",
  "正文最多 20000 个字符位，部分表情占多个字符位；原草稿未改动": "Textlimit beträgt 20000 Code-Einheiten; manche Emoji belegen mehrere. Ursprünglicher Entwurf unverändert.",
  "心情最多 80 个字符位，部分表情占多个字符位；原草稿未改动": "Stimmungslimit beträgt 80 Code-Einheiten; manche Emoji belegen mehrere. Ursprünglicher Entwurf unverändert.",
  "记录草稿无法读取；请先备份草稿文件再修复": "Kurznotizentwurf kann nicht gelesen werden. Sichern Sie die Entwurfsdatei vor der Reparatur.",
  "草稿已更新，请重新载入当前草稿": "Entwurf aktualisiert. Laden Sie den aktuellen Entwurf neu.",
  "此草稿已有待完成保存，请先重试保存；不能改写已准备的记录": "Für diesen Entwurf steht ein Speichervorgang aus. Versuchen Sie zuerst erneut zu speichern; vorbereitete Aufzeichnungen können nicht geändert werden.",
  "草稿已更新，此提交不会重复创建记录": "Entwurf aktualisiert; diese Übermittlung erstellt kein Duplikat",
  "请填写记录正文，不能只有空白": "Geben Sie Kurznotiztext ein; nur Leerzeichen sind nicht erlaubt",
  "心情不能只有空白；清空心情后也可以保存": "Stimmung darf nicht nur aus Leerzeichen bestehen. Leeren Sie sie, um ohne Stimmung zu speichern.",
  "提交版本已过期，请重新保存当前草稿": "Übermittlungsrevision abgelaufen. Speichern Sie den aktuellen Entwurf erneut.",
  "待完成记录属于原中央；恢复原节点后完成保存": "Ausstehende Aufzeichnung gehört zum ursprünglichen Knoten. Stellen Sie ihn wieder her, um das Speichern abzuschließen.",
  "待完成记录不能改写，请重新载入草稿后重试": "Ausstehende Aufzeichnung kann nicht geändert werden. Laden Sie den Entwurf neu und versuchen Sie es erneut.",
  "请为 --profile 指定环境短名": "Geben Sie nach --profile einen Umgebungsnamen an",
  "只允许指定一个 profile": "Es darf nur ein Profil angegeben werden",
  "Profile 需为 1–32 个小写字母、数字、下划线或连字符": "Das Profil muss aus 1–32 Kleinbuchstaben, Ziffern, Unterstrichen oder Bindestrichen bestehen",
  "开发或测试环境不能自动连接日常节点 47832；请使用独立节点，或在应用设置中明确配置": "Entwicklungs-/Testprofile können den täglichen Knoten 47832 nicht automatisch verwenden. Verwenden Sie einen separaten Knoten oder konfigurieren Sie ihn explizit in der App.",
  "存储切换的提交状态需要恢复；新旧副本均已保留，请退出并重新打开 Mote": "Die Übernahme des Speicherwechsels erfordert eine Wiederherstellung. Beide Kopien erhalten; beenden Sie Mote und öffnen Sie es erneut.",
  "存储目录含符号链接，不能安全迁移；原目录保持有效": "Der Speicher enthält symbolische Links und kann nicht sicher migriert werden. Ursprüngliches Verzeichnis bleibt aktiv.",
  "存储目录含特殊文件，不能安全迁移": "Der Speicher enthält Spezialdateien und kann nicht sicher migriert werden",
  "迁移文件校验失败，原目录保持有效": "Migrationsprüfung fehlgeschlagen; ursprüngliches Verzeichnis bleibt aktiv",
  "截图目录不能是符号链接或其他文件；请重新选择": "Screenshot-Verzeichnis darf kein symbolischer Link oder eine andere Datei sein. Wählen Sie erneut.",
  "存储目录归属标记无效": "Ungültige Speicher-Eigentumsmarkierung",
  "截图目录不可用；请连接原磁盘后重试，已有记录不会被空目录替代": "Screenshot-Verzeichnis nicht verfügbar. Schließen Sie die ursprüngliche Festplatte an und versuchen Sie es erneut; Aufzeichnungen werden nicht durch ein leeres Verzeichnis ersetzt.",
  "该存储目录不属于当前环境和设备，不能混用其他环境的队列": "Der Speicher gehört zu einer anderen Umgebung oder einem anderen Gerät. Warteschlangen können nicht geteilt werden.",
  "已选择的截图目录不可用；请连接原磁盘后重试。不会新建空队列或自动回退旧副本": "Ausgewähltes Screenshot-Verzeichnis nicht verfügbar. Schließen Sie die ursprüngliche Festplatte an und versuchen Sie es erneut. Es wird keine leere Warteschlange oder Ausweichkopie erstellt.",
  "迁移恢复需要的原目录不可用；请连接原磁盘后重试，不会创建空队列": "Das für die Wiederherstellung benötigte Originalverzeichnis ist nicht verfügbar. Schließen Sie die ursprüngliche Festplatte an; es wird keine leere Warteschlange erstellt.",
  "存储目录的节点绑定不完整；已保留迁移副本，请检查原磁盘": "Knotenbindung des Speichers unvollständig. Migrationskopien erhalten; prüfen Sie die ursprüngliche Festplatte.",
  "请选择 Mote 应用数据目录以外的文件夹，避免与其他环境或应用文件混用": "Wählen Sie einen Ordner außerhalb der Mote-App-Daten, um eine Vermischung von Umgebungen oder App-Dateien zu vermeiden",
  "所选位置已有 Mote 存储目录；请选择其他文件夹，避免覆盖已有记录": "Der ausgewählte Ort enthält bereits Mote-Speicher. Wählen Sie einen anderen Ordner, um das Überschreiben von Aufzeichnungen zu vermeiden.",
  "新旧存储目录不能相同或互相嵌套": "Altes und neues Speicherverzeichnis dürfen nicht identisch oder verschachtelt sein",
  "旧副本归属无法确认，已保留待处理": "Eigentum der alten Kopie kann nicht verifiziert werden; zur Prüfung erhalten",
  "迁移恢复记录无效": "Ungültiger Migrationswiederherstellungsdatensatz",
  "迁移记录与当前环境不匹配，请保留目录并检查配置": "Migrationsdatensatz passt nicht zu dieser Umgebung. Behalten Sie das Verzeichnis und prüfen Sie die Konfiguration.",
  "上次迁移副本尚未清理，请确认旧磁盘可用后重试": "Vorherige Migrationskopie wartet auf Bereinigung. Stellen Sie sicher, dass die alte Festplatte verfügbar ist, und versuchen Sie es dann erneut.",
  "目标位置与应用环境目录冲突": "Ziel steht im Konflikt mit dem App-Umgebungsverzeichnis",
  "新位置已存在文件，迁移不会覆盖或合并已有记录": "Ziel enthält bereits Dateien. Die Migration überschreibt oder führt keine Aufzeichnungen zusammen.",
  "新位置空间不足；请释放空间或选择其他位置": "Unzureichender Speicherplatz am Ziel. Geben Sie Speicherplatz frei oder wählen Sie einen anderen Ort.",
  "正在复制并校验存储文件": "Speicherdateien werden kopiert und geprüft",
