  "本地录音服务": "Lokaler Audiodienst",
  "更换服务地址或类型时，请重新填写或清除密钥": "Beim Ändern von Dienst-URL oder -Typ den Schlüssel ersetzen oder löschen",
  "归档方案不能设置处理步骤": "Nur-Archiv-Pläne können keine Verarbeitungsschritte festlegen",
  "所选处理插件不可用": "Ausgewähltes Verarbeitungs-Plugin nicht verfügbar",
  "方案需要选择内容提取插件": "Wählen Sie ein Inhaltsextraktions-Plugin für diesen Plan",
  "服务类型与处理插件不匹配": "Diensttyp passt nicht zum Verarbeitungs-Plugin",
  "分析步骤需要语言模型服务": "Die Analyse erfordert einen Sprachmodell-Dienst",
  "插件不支持参数 {0}": "Plugin unterstützt Parameter {0} nicht",
