  "请粘贴连接邀请 JSON 或 mote://connect 链接": "Fügen Sie Einladungs-JSON oder einen mote://connect-Link ein",
  "收到通知（首次观察）": "Benachrichtigung erhalten (erstmals beobachtet)",
  "通知更新": "Benachrichtigung aktualisiert",
  "通知移除": "Benachrichtigung entfernt",
  "用户解锁 / 在场": "Benutzer entsperrt / anwesend",
  "系统报告已锁定": "System meldet gesperrt",
  "系统报告未锁定": "System meldet entsperrt",
  "屏幕不可交互": "Bildschirm nicht interaktiv",
  "自定义接口": "Benutzerdefinierter Endpunkt",
  "选择接口协议，填写服务基址和支持工具调用的模型 ID。高级配置可设置请求头和厂商参数。": "Wählen Sie ein Protokoll, eine Basis-URL und eine tool-fähige Modell-ID. Erweiterte Einstellungen unterstützen Header und Anbieterparameter.",
  "DeepSeek 官方接口，保留其推理与多轮工具调用格式。模型 ID 以控制台为准。": "Offizielle DeepSeek-API mit Reasoning und mehrstufigen Tool-Calls. Modell-IDs finden Sie in der Konsole.",
  "阿里云 / 通义千问": "Alibaba Cloud / Qwen",
  "使用百炼 API key；工作空间与地域地址可按控制台修改，密钥必须与地域对应。": "Verwenden Sie einen Model-Studio-API-Schlüssel. Passen Sie Workspace- und Region-URL an Ihre Konsole an; der Schlüssel muss zur Region passen.",
  "火山方舟 / 豆包": "Volcengine Ark / Doubao",
  "使用方舟 API key；模型栏填写控制台的模型 ID 或推理接入点 ID。": "Verwenden Sie einen Ark-API-Schlüssel und geben Sie die Modell-ID oder Inference-Endpoint-ID aus der Konsole ein.",
  "智谱 / GLM": "Zhipu / GLM",
  "使用开放平台 API key；选择支持工具调用的模型，思考参数按该模型文档配置。": "Verwenden Sie einen Open-Platform-API-Schlüssel und ein tool-fähiges Modell. Konfigurieren Sie Reasoning gemäß dessen Dokumentation.",
  "月之暗面 / Kimi": "Moonshot / Kimi",
  "使用 Kimi 开放平台 API key；不同代际模型的思考参数不同，默认交给模型处理。": "Verwenden Sie einen Kimi-API-Schlüssel. Reasoning-Parameter variieren je nach Modellgeneration; automatisch ist Standard.",
  "使用 MiniMax API key。也可切换 Messages 协议并将地址改为 https://api.minimax.cn/anthropic。": "Verwenden Sie einen MiniMax-API-Schlüssel. Für Messages ändern Sie die URL zu https://api.minimax.cn/anthropic.",
  "百度智能云 / 千帆": "Baidu Cloud / Qianfan",
  "使用新版 API Key（Bearer）；不要填写旧版 OAuth access_token。模型须支持工具调用。": "Verwenden Sie den neueren API-Schlüssel (Bearer), nicht ein altes OAuth access_token. Das Modell muss Tools unterstützen.",
  "腾讯云 / TokenHub": "Tencent Cloud / TokenHub",
  "腾讯新版模型服务，使用 TokenHub 新密钥；从旧混元平台迁移时需要同时更换地址和密钥。": "Tencents neuerer Modelldienst verwendet einen neuen TokenHub-Schlüssel. Bei der Migration vom alten Hunyuan müssen URL und Schlüssel geändert werden.",
  "腾讯混元（原平台）": "Tencent Hunyuan (alt)",
  "供已有混元账户使用；新接入建议选择 TokenHub，两个平台的密钥不能直接复用。": "Für bestehende Hunyuan-Konten. Neue Integrationen sollten TokenHub verwenden; die Schlüssel sind nicht austauschbar.",
  "硅基流动 / SiliconFlow": "SiliconFlow",
  "填写完整模型 ID；工具调用与思考能力取决于所选模型。": "Geben Sie die vollständige Modell-ID ein. Tool- und Reasoning-Unterstützung hängen vom Modell ab.",
  "讯飞 / 星火": "iFlytek / Spark",
  "使用 HTTP 服务的 APIPassword。预设为 X2 地址，其他版本请按控制台修改地址和模型 ID。": "Verwenden Sie das APIPassword des HTTP-Dienstes. X2 ist die voreingestellte URL; passen Sie URL und Modell-ID in der Konsole für andere Versionen an.",
  "阶跃星辰 / StepFun": "StepFun",
  "使用开放平台 API key；Step Plan 套餐需改为 https://api.stepfun.com/step_plan/v1 并选择套餐可用模型。": "Verwenden Sie einen Open-Platform-API-Schlüssel. Step Plan erfordert https://api.stepfun.com/step_plan/v1 und ein in Ihrem Plan verfügbares Modell.",
  "默认使用 Responses；也可切换 Chat Completions。填写账户可用的模型 ID。": "Standardmäßig Responses; Chat Completions wird ebenfalls unterstützt. Geben Sie eine für Ihr Konto verfügbare Modell-ID ein.",
  "使用原生 Messages 与工具调用，凭据为 Claude API key。": "Native Messages und Tool-Calls mit einem Claude-API-Schlüssel.",
  "Google 原生接口；使用 Gemini API key，保留工具调用中的思考签名。选择支持工具调用的模型。": "Native Google-API mit einem Gemini-Schlüssel, bewahrt Thought-Signaturen in Tool-Calls. Wählen Sie ein tool-fähiges Modell.",
  "填写 Azure 资源的 https://资源名.openai.azure.com/openai/v1 地址；模型栏填写部署名称，密钥通过 api-key 请求头发送。": "Geben Sie Ihre Azure-Ressourcen-URL https://ressource.openai.azure.com/openai/v1 und den Deployment-Namen als Modell ein. Der Schlüssel wird im api-key-Header gesendet.",
  "使用 Responses 接口和 xAI API key；也可切换兼容 Chat Completions。": "Responses mit einem xAI-Schlüssel; kompatible Chat Completions wird ebenfalls unterstützt.",
  "使用 Chat Completions；选择支持函数调用的模型。": "Chat Completions; wählen Sie ein funktionsfähiges Modell.",
  "Groq 官方兼容接口；模型的参数和工具能力以控制台说明为准。": "Offizielle Groq-kompatible API. Modellparameter und Tool-Fähigkeiten finden Sie in der Konsole.",
  "填写完整模型 ID；请选择支持 tools 的模型与路由。": "Geben Sie die vollständige Modell-ID ein und wählen Sie ein tools-fähiges Modell und Routing.",
  "地址属于中央所在机器。需先启动 Ollama 并安装支持工具调用的模型。": "Diese Adresse liegt auf dem zentralen Host. Starten Sie zuerst Ollama und installieren Sie ein tool-fähiges Modell.",
  "先在中央所在机器启动 LM Studio 服务，模型须支持工具调用。": "Starten Sie zuerst LM Studio auf dem zentralen Host. Das Modell muss Tools unterstützen.",
  "本机图片批量去重": "Lokale Bild-Massendeduplizierung",
  "扫描开始时本机保存的全部采集图片，按时间从早到晚扫描，与上一张保留图比较；相似则标记为重复，否则更新保留图。应用或尺寸变化时重新开始比较，不限制时间间隔。只处理本机副本；已上传中央的记录仍然保留。待决定区独立保存在本机，不参与同步和自动清理，仍占用磁盘空间。": "Scannt alle beim Start vorhandenen lokalen Erfassungsbilder, älteste zuerst, und vergleicht sie mit dem zuletzt behaltenen Bild. Ähnliche Bilder werden Kandidaten; sonst rückt das behaltene Bild vor. App- oder Größenwechsel setzen den Vergleich zurück; kein Zeitabstandslimit. Nur lokale Kopien sind betroffen; zentrale Aufzeichnungen bleiben erhalten. Die Quarantäne ist lokal, von Synchronisierung und automatischer Bereinigung ausgeschlossen und belegt weiterhin Speicherplatz.",
  "扫描和处理均在后台执行，可以离开本页。取消后已完成的处理保留，剩余记录留在原处。": "Scan und Verarbeitung laufen im Hintergrund. Sie können diese Seite verlassen. Ein Abbruch behält abgeschlossene Arbeit und lässt übrige Aufzeichnungen an Ort und Stelle.",
