  "只清空累计数字和最近事件，并记录新起算时间。不会删除队列、模型、配置或中央资料。": "Löscht nur Zähler und letzte Ereignisse und setzt eine neue Startzeit. Warteschlangen, Modelle, Konfiguration und zentrale Daten bleiben erhalten.",
