  "\n{0}\n{1} · {2} · {3}\n待发 {4} 个版本 · 最近扫描 {5}\n{6}": "\n{0}\n{1} · {2} · {3}\n{4} ausstehende Versionen · Letzter Scan {5}\n{6}",
