  "等待系统安装确认；未弹出时查看通知，或取消待确认安装后重试": "Warten auf Systembestätigung. Prüfen Sie die Benachrichtigungen, falls kein Dialog erscheint, oder brechen Sie die ausstehende Installation ab und versuchen Sie es erneut.",
  "系统已完成更新；已有应用数据保留": "Systemupdate abgeschlossen; App-Daten bleiben erhalten",
  "请在系统允许此应用安装更新，返回后再次点击安装": "Erlauben Sie dieser App in den Systemeinstellungen die Installation von Updates, kehren Sie dann zurück und tippen Sie auf „Installieren“",
  "APK 签名与当前应用不兼容或无效，已阻止更新；不会卸载旧应用": "APK-Signatur inkompatibel oder ungültig. Update blockiert; die alte App wird nicht deinstalliert.",
  "APK 大小或 SHA-256 不匹配，未交给系统安装": "APK-Größe oder SHA-256 stimmt nicht überein; nicht zur Installation übergeben",
  "APK 包名、版本或系统要求与当前应用不符，已阻止安装": "APK-Paketname, -Version oder Systemanforderungen passen nicht zur aktuellen App; Installation blockiert",
