  "备份属于不同中央。连接原节点后导入": "Backup gehört zu einem anderen Knoten. Verbinden Sie ihn vor dem Import.",
  "备份中存在同 ID 内容冲突，未导入": "Backup enthält Inhaltskonflikte bei gleicher ID; nicht importiert",
  "未命名日历": "Unbenannter Kalender",
  "日历提供者不可用": "Kalenderanbieter nicht verfügbar",
  "已选择日历不可用，请重新连接；不会把权限丢失视为删除": "Ausgewählter Kalender nicht verfügbar. Verbinden Sie erneut; ein Berechtigungsverlust gilt nicht als Löschung.",
  "\n地点：{0}": "\nOrt: {0}",
  "日历提供者没有返回扫描结果": "Kalenderanbieter lieferte keine Scanergebnisse",
  "文件不可读": "Datei nicht lesbar",
  "文件目录不可用": "Dateiverzeichnis nicht verfügbar",
  "所选文件暂不可用；不会把访问失败视为删除": "Ausgewählte Datei derzeit nicht verfügbar; ein Zugriffsfehler gilt nicht als Löschung",
  "文件提供者不可用": "Dateianbieter nicht verfügbar",
  "首次使用：在中央网页「行动」开启发现，并授权此设备查看跨来源的建议及原文片段。": "Erste Nutzung: Aktivieren Sie die Erkennung und autorisieren Sie dieses Gerät in den zentralen „Aktionen“-Einstellungen, um quellenübergreifende Vorschläge und Originalauszüge anzuzeigen.",
  "刷新并同步已确认日程": "Aktualisieren und bestätigte Termine synchronisieren",
  "正在读取日程建议…": "Terminvorschläge werden geladen…",
  "正在连接日历…": "Kalender werden verbunden…",
  "正在同步已确认日程…": "Bestätigte Termine werden synchronisiert…",
  "尚未发现日程。上传资料或继续采集后会自动分析。": "Noch keine Termine erkannt. Die Analyse läuft nach Uploads oder weiterer Erfassung automatisch.",
  "等待保存回执": "Warten auf Speicherbestätigung",
  "查看原文依据": "Nachweis im Original anzeigen",
  "原文依据": "Originalnachweis",
  "核对并添加到日历": "Prüfen und zum Kalender hinzufügen",
  "忽略这条建议": "Vorschlag ignorieren",
  "正在保存选择…": "Auswahl wird gespeichert…",
  "写入 / 核实保存结果": "Schreiben / Speichergebnis verifizieren",
  "正在写入已确认日程…": "Bestätigter Termin wird geschrieben…",
  "请先连接本机日历": "Verbinden Sie zuerst lokale Kalender",
  "请先连接本机日历，并在系统日历中添加可写账户": "Verbinden Sie zuerst lokale Kalender und fügen Sie im Systemkalender ein beschreibbares Konto hinzu",
  "点击日期字段选择时间。全天日程的结束日期不包含当天。时区可修改。": "Tippen Sie auf Datumsfelder, um Zeiten zu wählen. Bei ganztägigen Terminen ist das Enddatum exklusiv. Die Zeitzone kann angepasst werden.",
  "夏令时切换时间不明确，请改用 UTC 时区": "Mehrdeutiger Sommerzeitwechsel. Verwenden Sie stattdessen UTC.",
  "添加到已有日历": "Zu vorhandenem Kalender hinzufügen",
  "确认添加": "Hinzufügen bestätigen",
  "请核对完整日期、时间、时区和标题": "Prüfen Sie vollständiges Datum, Uhrzeit, Zeitzone und Titel",
  "正在确认并写入日程…": "Termin wird bestätigt und geschrieben…",
  "未授权，不读取或写入日历。可随时重新连接。": "Nicht autorisiert; Kalender werden weder gelesen noch geschrieben. Sie können jederzeit erneut verbinden.",
  "正在恢复本机存储，请稍候": "Lokaler Speicher wird wiederhergestellt. Bitte warten.",
  "本机存储恢复失败": "Wiederherstellung des lokalen Speichers fehlgeschlagen",
  "内部应用空间": "Interner App-Speicher",
  "存储卡应用空间 {0}": "SD-Karten-App-Speicher {0}",
  "本机存储应用空间": "Lokaler App-Speicher",
  "所选存储介质不可用，请重新连接；不会切换为空目录": "Ausgewählter Speicher nicht verfügbar. Verbinden Sie ihn erneut; es wird nicht zu einem leeren Verzeichnis gewechselt.",
  "存储路径不在本应用授权空间内": "Speicherpfad liegt außerhalb des autorisierten Bereichs dieser App",
  "所选目标存储暂不可用": "Ausgewählter Zielspeicher derzeit nicht verfügbar",
  "投屏授权已结束（锁屏、系统或用户停止），请打开应用重新授权": "Autorisierung der Bildschirmfreigabe beendet (Sperrbildschirm, System oder Benutzerstopp). Öffnen Sie die App, um sie erneut zu erteilen.",
  "已锁屏，投屏采集结束；解锁后请重新授权": "Bildschirm gesperrt; Bildschirmfreigabe beendet. Autorisieren Sie nach dem Entsperren erneut.",
