  "OCR 模式无效": "Ungültiger OCR-Modus",
  "通知事件已启用": "Benachrichtigungsereignisse aktiviert",
  "亮屏与锁定事件已启用": "Bildschirm- und Sperrereignisse aktiviert",
  "部分系统事件未能保存，请检查本机存储；事件历史可能不完整": "Einige Systemereignisse konnten nicht gespeichert werden. Prüfen Sie den lokalen Speicher; der Ereignisverlauf kann unvollständig sein.",
  "遮罩坐标必须在 0..1": "Maskenkoordinaten müssen zwischen 0 und 1 liegen",
  "遮罩右下坐标必须大于左上坐标": "Die unteren rechten Maskenkoordinaten müssen größer als die oberen linken sein",
  "每行遮罩需要 left,top,right,bottom 四个坐标": "Jede Maskenzeile benötigt vier Koordinaten: left,top,right,bottom",
  "无法可靠识别窗口，已暂停：排除规则要求完整应用信息": "Pausiert: Fenster konnten nicht zuverlässig identifiziert werden, und Ausschlussregeln benötigen vollständige App-Informationen.",
  "当前屏幕包含你排除的应用": "Der aktuelle Bildschirm enthält eine ausgeschlossene App",
