  "请使用 HTTPS；仅 debug APK 可显式允许私有 IP 的 HTTP": "Verwenden Sie HTTPS; nur Debug-APKs können HTTP für private IPs explizit erlauben",
  "本地隐私模型仅允许手机本机 loopback 地址": "Lokale Datenschutzmodelle erfordern eine Loopback-Adresse auf diesem Telefon",
  "同步调度暂不可用，记录保留在本机，请稍后重试": "Synchronisierungsplanung ist nicht verfügbar. Aufzeichnungen bleiben auf diesem Gerät; versuchen Sie es später erneut.",
  "正在应用设置，请完成后重试本次扫描或立即同步": "Einstellungen werden angewendet. Wiederholen Sie den Scan oder die Synchronisierung nach Abschluss.",
  "仅保存在本机 · 连接节点后可同步": "Auf diesem Gerät gespeichert · Knoten verbinden, um zu synchronisieren",
  "等待约定同步时间 · 系统省电可能推迟后台运行": "Warten auf die geplante Synchronisierungszeit · Energiesparen kann Hintergrundarbeit verzögern",
  "请选择有效同步方式": "Wählen Sie einen gültigen Synchronisierungsmodus",
  "同步间隔为 1..1440 分钟": "Synchronisierungsintervall muss 1–1440 Minuten betragen",
  "批量同步数量为 1..500 条": "Synchronisierungs-Batchgröße muss 1–500 Aufzeichnungen betragen",
  "JSONL 合并窗口为 1..1440 分钟": "JSONL-Zusammenführungsfenster muss 1–1440 Minuten betragen",
  "Mote · 你的个人上下文": "Mote · Ihr persönlicher Kontext",
  "连接节点": "Knoten verbinden",
  "正在初始化": "Wird initialisiert",
  "权限检查中": "Berechtigungen werden geprüft",
  "重新打开 Mote 以恢复存储": "Öffnen Sie Mote erneut, um den Speicher wiederherzustellen",
  "正在读取本地配置与队列…": "Lokale Konfiguration und Warteschlange werden geladen…",
  "采集与记录待传": "Erfassungen und Notizen warten auf Upload",
  "中央确认接收后移出队列": "Nach Bestätigung durch den zentralen Knoten aus der Warteschlange entfernt",
  "断网时也能安全保留": "Auch offline sicher aufbewahrt",
  "最近采样": "Letzte Abtastung",
  "屏幕录制权限 ↗": "Bildschirmaufnahme-Berechtigung ↗",
  "正在读取": "Wird geladen",
  "关闭窗口后仍驻留菜单栏；停止采集后，已有记录仍按上传策略同步；退出应用后暂停。": "Mote bleibt nach dem Schließen des Fensters in der Menüleiste. Beim Stoppen der Erfassung werden vorhandene Aufzeichnungen weiterhin nach Ihrer Richtlinie synchronisiert; Beenden pausiert die Synchronisierung.",
  "展示方式": "Anzeige",
  "全部截图": "Alle Screenshots",
  "返回采集时段": "Zurück zu den Erfassungssitzungen",
  "记录详情": "Aufzeichnungsdetails",
  "关闭详情": "Details schließen",
  "连接系统日历": "Systemkalender verbinden",
  "连接 Coding Agent": "Coding-Agent verbinden",
  "采集所选 Agent": "Ausgewählte Agents erfassen",
  "选择一个已授权日历": "Autorisierten Kalender wählen",
  "立即检查并上传": "Jetzt prüfen und hochladen",
  "检查间隔（秒）": "Prüfintervall (Sekunden)",
  "文件来源扩展名（可补充）": "Dateierweiterungen (nach Bedarf ergänzen)",
  "排除相对路径（每行一项）": "Ausgeschlossene relative Pfade (einer pro Zeile)",
  "精确路径或目录前缀，适用于文件和编码对话来源。": "Genaue Pfade oder Verzeichnispräfixe, für Datei- und Coding-Konversationsquellen.",
  "上传前遮盖的确切文字（每行一项，可选）": "Genauer Text, der vor dem Upload geschwärzt wird (optional; einer pro Zeile)",
  "跟踪删除": "Löschungen verfolgen",
  "仅完整成功扫描后标记范围内消失项；中央历史版本仍保留。默认关闭。": "Nur ein vollständig erfolgreicher Scan markiert verschwundene Elemente im Bereich; der zentrale Verlauf bleibt erhalten. Standardmäßig deaktiviert.",
  "来源权限与保存方式": "Quellenberechtigungen und Aufbewahrung",
  "日历只读过去 30 天至未来 90 天内的所选日历，不修改系统日历。权限仅在点击连接日历时申请。App 驻留时持续检查本地变化，按统一上传策略同步；退出后暂停，下次打开恢复。": "Es wird nur der ausgewählte Kalender von 30 Tagen zurück bis 90 Tage voraus gelesen; Systemkalender werden nie geändert. Die Berechtigung wird nur beim Verbinden eines Kalenders angefragt. Mote prüft lokale Änderungen, solange es läuft, und folgt der gemeinsamen Upload-Richtlinie; nach dem Beenden pausieren die Prüfungen bis zum nächsten Start.",
  "每来源待传上限 4000 版本 / 32 MiB。路径与待传正文只保存在本机私有来源目录，不进入支持包。更换节点或令牌使用独立同步状态；原节点待传版本不会发送到新节点。": "Jede Quelle kann 4.000 Versionen / 32 MiB in der Warteschlange halten. Pfade und ausstehende Texte bleiben in einem privaten lokalen Quellenverzeichnis und werden von Support-Paketen ausgeschlossen. Beim Wechsel von Knoten oder Token wird ein separater Synchronisierungsstatus verwendet; alte ausstehende Versionen werden nie an einen neuen Knoten gesendet.",
  "日历权限 ↗": "Kalenderberechtigung ↗",
  "连接与设备": "Verbindung und Gerät",
  "中央、连接邀请与设备名称": "Zentraler Knoten, Einladungen und Gerätename",
  "上传与同步": "Upload und Synchronisierung",
  "实时、定时、批量或仅手动上传": "Echtzeit-, geplante, Batch- oder nur manuelle Uploads",
  "采样频率、文字识别、运行方式与本地队列": "Abtastrate, Texterkennung, Betrieb und lokale Warteschlange",
  "隐私与过滤": "Datenschutz und Filter",
  "应用范围、遮挡区域与本地视觉审查": "App-Bereich, Masken und lokale visuelle Überprüfung",
  "版本信息与应用更新": "Versionsinformationen und App-Updates",
  "高级": "Erweitert",
  "模型参数、性能诊断、支持包与数据迁移": "Modellparameter, Leistungsdiagnose, Support-Pakete und Datenmigration",
  "本机统计": "Lokale Statistiken",
  "查看当前队列、模型与处理状态。": "Status von Warteschlange, Modell und Verarbeitung anzeigen.",
  "运行概况": "Laufzeitübersicht",
  "队列与模型状态实时更新。": "Status von Warteschlange und Modell wird in Echtzeit aktualisiert.",
  "需要处理计数、耗时和 CPU 数据时，可开启本机诊断。": "Aktivieren Sie lokale Diagnose für Zähler, Zeitmessung und CPU-Daten.",
  "诊断仅记录数值与固定阶段事件，不上传个人正文。": "Die Diagnose zeichnet nur Zahlen und feste Phasenereignisse auf; persönliche Inhalte werden nie hochgeladen.",
  "采样时长是同应用两次采样之间的设备活动估计，不等于你的注意力时间。": "Die Abtastdauer schätzt die Geräteaktivität zwischen zwei Abtastungen derselben App; sie misst nicht Ihre Aufmerksamkeit.",
  "使用连接邀请": "Verbindungseinladung verwenden",
  "在中央仓库的“设备连接”中生成邀请，然后粘贴或导入。": "Erstellen Sie eine Einladung unter „Geräteverbindungen“ im Zentralarchiv und fügen Sie sie ein oder importieren Sie sie.",
  "推荐": "Empfohlen",
  "请仅使用可信的中央地址。预览不会发送网络请求。": "Verwenden Sie nur eine vertrauenswürdige zentrale Adresse. Die Vorschau sendet keine Netzwerkanfragen.",
  "预览连接": "Verbindungsvorschau",
  "导入 JSON": "JSON importieren",
  "导入二维码图片": "QR-Bild importieren",
