  "两张图片按原图尺度对齐；滚动任一画面可同步查看细节。质量参数不是文件压缩百分比。": "Beide Bilder sind im Originalmaßstab ausgerichtet; beim Scrollen in einer Ansicht werden die Details synchronisiert. Der Qualitätsparameter ist kein Prozentsatz der Dateikomprimierung.",
