  "留空可仅在本机采集；远程地址使用 HTTPS。": "Leer lassen für rein lokale Erfassung; entfernte Adressen erfordern HTTPS.",
  "访问令牌": "Zugriffstoken",
  "使用系统密钥存储加密；不会展示已有令牌。": "Mit dem Systemschlüsselspeicher verschlüsselt; vorhandene Token werden nie angezeigt.",
  "将本机积存记录同步到这个节点": "Gesammelte lokale Aufzeichnungen mit diesem Knoten synchronisieren",
  "已绑定节点的待传记录始终属于原节点。清空地址不会解除绑定；迁移前请先完成上传或导出并移走旧队列。": "Ausstehende Aufzeichnungen, die an einen Knoten gebunden sind, gehören immer zu diesem. Das Leeren der Adresse löst die Bindung nicht. Schließen Sie vor der Migration den Upload ab oder exportieren und entfernen Sie die alte Warteschlange.",
  "本地采集和上传独立运行": "Lokale Erfassung und Uploads laufen unabhängig",
  "01 · 先保存": "01 · Zuerst speichern",
  "02 · 按策略发送": "02 · Nach Richtlinie senden",
  "停止采集不会停止已有记录的同步。应用运行时执行计划；电脑休眠或应用退出时延后。": "Das Stoppen der Erfassung stoppt nicht die Synchronisierung vorhandener Aufzeichnungen. Zeitpläne laufen, solange die App aktiv ist; Ruhezustand oder Beenden verzögert sie.",
  "管理连接地址 →": "Verbindungsadresse verwalten →",
  "仅采集主屏幕。锁屏和休眠时始终暂停。": "Nur der Hauptbildschirm wird erfasst. Die Erfassung pausiert immer bei Sperrung oder Ruhezustand.",
  "采样间隔（秒）": "Abtastintervall (Sekunden)",
  "相同画面复用本地图像，保留每次采样记录。": "Identische Bildschirme verwenden lokale Bilder wieder, wobei jede Abtastaufzeichnung erhalten bleibt.",
  "连续空闲后暂停（秒）": "Nach Leerlaufzeit pausieren (Sekunden)",
  "默认 300；设为 0 可关闭空闲检测。": "Standard 300; auf 0 setzen, um die Leerlauferkennung zu deaktivieren.",
  "运行与电源": "Betrieb und Stromversorgung",
  "让 Mote 按照你的设备使用方式运行。": "Passen Sie Mote an Ihre Gerätenutzung an.",
  "登录时打开 Mote": "Mote bei der Anmeldung öffnen",
  "应用启动后保持停止状态，需手动开始采集；已有队列按上传策略处理。": "Die Erfassung bleibt nach dem Start gestoppt, bis Sie sie manuell starten; vorhandene Warteschlangen folgen der Upload-Richtlinie.",
  "使用电池时暂停采集": "Erfassung im Akkubetrieb pausieren",
  "连接电源后恢复，减少移动使用时的资源消耗。": "Bei externer Stromversorgung fortsetzen, um den Ressourcenverbrauch unterwegs zu reduzieren.",
