  "选一个常用区域，再用滑块调整。示意图不读取屏幕。": "Wählen Sie einen gängigen Bereich und passen Sie ihn mit Schiebereglern an. Das Diagramm liest Ihren Bildschirm nicht.",
  "右上通知区": "Benachrichtigungsbereich oben rechts",
  "顶部菜单栏": "Obere Menüleiste",
