  "自定义区域 ＋": "Benutzerdefinierter Bereich ＋",
  "屏幕示意 · 遮挡区域不会保存": "Bildschirmdiagramm · Maskierte Bereiche werden nicht gespeichert",
  "遮挡相对主屏幕左上角定位，保存和文字识别之前生效。添加后请根据实际屏幕布局调整范围。": "Masken beziehen sich auf die obere linke Ecke des Hauptbildschirms und greifen vor dem Speichern und der OCR. Passen Sie sie an Ihr tatsächliches Bildschirmlayout an.",
  "遮挡区域 JSON": "Maskenbereiche JSON",
  "x / y / width / height 使用 0–1 的比例。编辑后离开输入框即可更新示意。": "x / y / width / height verwenden Verhältnisse von 0 bis 1. Verlassen Sie das Feld nach dem Bearbeiten, um das Diagramm zu aktualisieren.",
  "设备元数据": "Gerätemetadaten",
  "选择是否附带设备运行环境。": "Wählen Sie, ob Geräteumgebungsdetails enthalten sein sollen.",
  "上传设备与采样元数据": "Geräte- und Abtastmetadaten hochladen",
  "关闭后仍保留基本应用与时间记录；文件来源的时间元数据不受此开关影响。": "Grundlegende App- und Zeitaufzeichnungen bleiben auch deaktiviert erhalten; Zeitmetadaten von Dateiquellen sind nicht betroffen.",
  "可能包含哪些数据": "Was enthalten sein kann",
  "可包含系统版本、硬件型号、语言时区、电量、温度级别、空闲时间、锁屏状态、可用空间，以及完整内容截图参数；不包含序列号、SSID 或定位。平台未提供的值留空。": "Kann Betriebssystemversion, Hardwaremodell, Sprache und Zeitzone, Akkustand, Temperaturniveau, Leerlaufzeit, Sperrstatus, freien Speicherplatz und Screenshot-Parameter für vollständige Inhalte enthalten. Seriennummern, SSIDs und Standort sind ausgeschlossen. Nicht verfügbare Werte werden weggelassen.",
  "最大生成 token": "Maximale Ausgabetokens",
  "图像与资源优化": "Bild- und Ressourcenoptimierung",
  "打开图片压缩预览 →": "Bildkomprimierungs-Vorschau öffnen →",
  "在存储占用和文字清晰度之间调整。": "Balancieren Sie Speicherverbrauch und Textklarheit.",
  "较低质量减少存储，可能影响小字识别。": "Niedrigere Qualität spart Speicher, kann aber die Erkennung kleiner Schrift beeinträchtigen.",
  "本机诊断": "Lokale Diagnose",
  "不记录截图、OCR、记录、审查策略、节点地址或令牌。电量是整台设备的变化，不是 Mote 的耗电归因。": "Zeichnet keine Screenshots, OCR, Kurznotizen, Überprüfungsrichtlinien, Knotenadressen oder Token auf. Akkuänderungen betreffen das gesamte Gerät, nicht den Stromverbrauch von Mote.",
  "诊断采样（秒）": "Diagnoseintervall (Sekunden)",
