  "导出安全支持包": "Sicheres Support-Paket exportieren",
  "查看本地日志": "Lokale Protokolle anzeigen",
  "设置保存后立即生效，保持当前采集开停状态。": "Gespeicherte Einstellungen wirken sofort und behalten den aktuellen Erfassungsstatus bei.",
  "还原修改": "Änderungen zurücksetzen",
  "本地数据与迁移": "Lokale Daten und Migration",
  "队列备份包含已脱敏截图与 OCR，不含访问令牌。中央仓库请在服务端导出。": "Warteschlangen-Backups enthalten geschwärzte Screenshots und OCR, aber keine Zugriffstoken. Exportieren Sie das Zentralarchiv vom Server.",
