  "发布说明 ↗": "Versionshinweise ↗",
  "更新来源与安装说明": "Update-Quelle und Installation",
  "更新来自 GitHub utopiafar/mote，只接受内置发布公钥验证通过的安装包。": "Updates kommen von GitHub utopiafar/mote. Nur Installationspakete, die mit dem integrierten öffentlichen Release-Schlüssel verifiziert wurden, werden akzeptiert.",
  "安装前请保存尚未提交的设置。记录草稿会先保存；所有 profile、Keychain、草稿、队列与模型目录保留。请先退出同一 App 的其他 profile。ad-hoc 签名更新后，macOS 可能再次要求授权；不会重置你的资料。安装目录不可写时可使用 Finder 手动替换 App。": "Speichern Sie vor der Installation noch nicht übermittelte Einstellungen. Kurznotiz-Entwürfe werden zuerst gespeichert; alle Profile, Keychain-Einträge, Entwürfe, Warteschlangen und Modellverzeichnisse bleiben erhalten. Beenden Sie zuerst andere Profile dieser App. Nach einem Ad-hoc-signierten Update kann macOS erneut Berechtigungen anfordern; Ihre Daten werden nicht zurückgesetzt. Ist das Installationsverzeichnis nicht beschreibbar, ersetzen Sie die App manuell im Finder.",
  "关闭窗口后 Mote 仍会驻留菜单栏；如需完全退出，请使用菜单栏中的退出操作。": "Mote bleibt nach dem Schließen des Fensters in der Menüleiste. Verwenden Sie „Beenden“ in der Menüleiste, um vollständig zu beenden.",
  "由你指定原文，不自动推断": "Sie geben den Originaltext an; er wird nie automatisch abgeleitet",
  "粘贴邀请 JSON 或 mote://connect?data=…": "Einladungs-JSON oder mote://connect?data=… einfügen",
