  "Mote 使用独立的 CLI 配置。首次使用先创建应用，也可以填写已有应用的 App ID 和 App Secret。": "Mote verwendet eine separate CLI-Konfiguration. Erstellen Sie eine App oder geben Sie eine vorhandene App-ID und ein App-Secret ein.",
