  "最近成功同步：": "Letzte erfolgreiche Synchronisierung: ",
  "还没有完成过同步。": "Es wurde noch keine Synchronisierung abgeschlossen.",
  "查看来源与归档": "Quellen und Archive anzeigen",
  "断开连接": "Verbindung trennen",
  "请先保存修改后的同步范围。": "Speichern Sie zuerst den geänderten Synchronisierungsbereich.",
  "断开会停止读取并暂停这些来源，保留已归档资料。飞书端授权及 CLI 凭据仍保留，可在飞书中单独撤销。": "Das Trennen stoppt Lesevorgänge und pausiert diese Quellen, wobei archivierte Inhalte erhalten bleiben. Feishu-Autorisierung und CLI-Anmeldedaten bleiben bestehen; widerrufen Sie den Zugriff separat in Feishu.",
  "连接已断开，历史归档已保留。": "Verbindung getrennt. Frühere Archive bleiben erhalten.",
  "确认断开": "Trennen bestätigen",
  "服务端尚未安装 Lark CLI。请点击安装，然后重新检测。": "Lark CLI ist nicht auf dem Server installiert. Installieren Sie es und prüfen Sie erneut.",
  "尚未配置飞书应用。请创建应用或填写已有应用凭据。": "Es ist keine Feishu-App konfiguriert. Erstellen Sie eine oder geben Sie vorhandene App-Anmeldedaten ein.",
  "尚未连接飞书账号，请完成只读授权。": "Es ist kein Feishu-Konto verbunden. Schließen Sie die Nur-Lese-Autorisierung ab.",
  "读取权限未完整授予。请在飞书应用后台开通下方只读权限，然后重新授权。": "Leseberechtigungen sind unvollständig. Aktivieren Sie die unten aufgeführten Nur-Lese-Scopes in der App-Konsole und autorisieren Sie erneut.",
  "授权链接已过期，请重新发起登录。": "Der Autorisierungslink ist abgelaufen. Starten Sie eine neue Anmeldung.",
  "检测到账号变化，已暂停旧来源。请重新授权并选择同步范围。": "Das Konto hat sich geändert. Frühere Quellen sind pausiert. Autorisieren Sie erneut und wählen Sie einen Synchronisierungsbereich.",
  "另一个操作正在进行，请稍后重试。": "Ein anderer Vorgang läuft. Versuchen Sie es gleich erneut.",
  "操作超时。请检查服务端网络，或重新发起授权。": "Der Vorgang hat das Zeitlimit überschritten. Prüfen Sie das Servernetzwerk oder starten Sie die Autorisierung erneut.",
  "飞书 CLI 操作未完成。请检查网络、应用权限及服务账号的系统钥匙串访问，再重试。": "Der Feishu-CLI-Vorgang ist fehlgeschlagen. Prüfen Sie Netzwerk, App-Berechtigungen und den Keychain-Zugriff des Dienstkontos, dann versuchen Sie es erneut.",
  "操作已取消，可以重新开始。": "Vorgang abgebrochen. Sie können neu beginnen.",
  "选中的日历不再可读，请重新加载日历列表。": "Ein ausgewählter Kalender ist nicht mehr lesbar. Laden Sie die Kalenderliste neu.",
  "请填写飞书或 Lark 的 docx、wiki 文档链接或文档 token。": "Geben Sie einen Feishu- oder Lark-docx-/wiki-Dokumentlink oder ein Dokument-Token ein.",
  "飞书返回格式不符合预期，本次未标记同步成功。请检查 CLI 版本和文档访问权限。": "Feishu hat eine unerwartete Antwort zurückgegeben. Die Synchronisierung wurde nicht als erfolgreich markiert. Prüfen Sie die CLI-Version und Dokumentberechtigungen.",
  "飞书操作失败，请重新检测连接后重试。": "Der Feishu-Vorgang ist fehlgeschlagen. Prüfen Sie die Verbindung und versuchen Sie es erneut.",
  "授权链接已复制。": "Autorisierungslink kopiert.",
  "复制失败，请使用二维码或授权链接。": "Kopieren fehlgeschlagen. Verwenden Sie den QR-Code oder Autorisierungslink.",
  "复制授权链接": "Autorisierungslink kopieren",
  "如果无法打开，可复制链接到浏览器，或扫码。": "Wenn sich der Link hier nicht öffnen lässt, kopieren Sie ihn in einen Browser oder scannen Sie den QR-Code.",
