  "处理队列已停用": "Verarbeitungsspur deaktiviert",
  "处理队列已停用，请启用后继续。": "Die Verarbeitungsspur ist deaktiviert. Aktivieren Sie sie, um fortzufahren.",
  "使用所选语言模型合并自然发言轮次": "Das ausgewählte Sprachmodell zum Zusammenführen natürlicher Sprechwechsel verwenden",
  "需要说话人分离插件": "Plugin zur Sprechertrennung erforderlich",
  "每个方案拥有自己的参数。界面字段来自已加载的 Cordis 插件；密钥在下方服务中统一管理。本地多人录音保留未校正逐字记录；摘要与语义分析使用所选模型。": "Jeder Plan hat eigene Parameter. Die Felder stammen von geladenen Cordis-Plugins; verwalten Sie Schlüssel unten unter „Dienste“. Lokale Mehrsprecher-Aufnahmen bewahren unbearbeitete Transkripte; Zusammenfassungen und semantische Analysen verwenden das ausgewählte Modell.",
  "已就绪": "Bereit",
