  "图片默认使用中央图片方案，原件保存后自动处理。": "Bilder folgen dem zentralen Bildplan und werden nach dem Speichern der Originale automatisch verarbeitet.",
  "跟随默认设置": "Standard übernehmen",
  "仅保存原件": "Nur Originale speichern",
  "正式接纳的截图、导入图片、同步图片和资料附件共享中央方案。原件先保存，各步骤独立完成。": "Angenommene Screenshots, importierte Bilder, synchronisierte Bilder und Materialanlagen teilen sich den zentralen Plan. Originale werden zuerst gespeichert, und jeder Schritt wird unabhängig abgeschlossen.",
  "自动处理新图片": "Neue Bilder automatisch verarbeiten",
  "文字识别服务": "OCR-Dienst",
  "后台理解画面与来源上下文": "Bilder und Quellenkontext im Hintergrund verstehen",
  "内容理解使用中央文件分析模型：{0}": "Das Inhaltsverständnis verwendet das zentrale Dateianalysemodell: {0}",
  "查看记忆设置": "Erinnerungseinstellungen anzeigen",
  "服务、插件参数与来源覆盖在文件处理策略中维护。图片设置通过引用复用这些配置。": "Dienste, Plugin-Parameter und Quellenüberschreibungen werden in den Dateiverarbeitungsrichtlinien verwaltet. Bildeinstellungen nutzen diese Konfigurationen per Referenz wieder.",
  "查看处理策略": "Verarbeitungsrichtlinien anzeigen",
  "允许图片发往已选择的远程 OCR 服务": "Senden von Bildern an den ausgewählten Remote-OCR-Dienst erlauben",
  "保存图片设置": "Bildeinstellungen speichern",
  "补处理已有图片": "Vorhandene Bilder nachbearbeiten",
  "选择范围后一次安排，中央会持续分批执行。补齐会复用已有成果；重新计算会产生新版本。": "Wählen Sie einen Bereich und planen Sie ihn einmal. Der zentrale Knoten führt stapelweise weiter aus. Das Ergänzen fehlender Schritte nutzt vorhandene Ergebnisse wieder; die Neuberechnung erzeugt neue Versionen.",
  "处理方式": "Verarbeitungsmodus",
