  "正在分批安排": "Stapelweise Einplanung läuft",
  "处理状态": "Verarbeitungsstatus",
  "统一文字识别、画面理解与历史补处理": "Vereinheitlichte OCR, Bildverständnis und Verarbeitung älterer Bilder",
  "图片处理": "Bildverarbeitung",
  "图片衍生成果": "Abgeleitete Bildergebnisse",
  "原件不可用": "Original nicht verfügbar",
  "图片处理成果请使用 npm run backup 完整备份；JSON 导出不包含图片理解版本。": "Verwenden Sie npm run backup für ein vollständiges Backup der Bildverarbeitungsergebnisse; der JSON-Export enthält keine Bildinterpretationsversionen.",
  "原始采集记录": "Ursprüngliche Erfassungsaufzeichnungen",
