  "包括 Coding Agent 会话；可读内容不等待记忆整理。": "Enthält Coding-Agent-Sitzungen. Lesbarer Inhalt wartet nicht auf die Erinnerungsverarbeitung.",
  "资料目录已变化，请返回第一页继续浏览。": "Die Bibliothek hat sich geändert. Kehren Sie zur ersten Seite zurück, um weiter zu durchsuchen.",
  "部分产物仍在处理，可先阅读已有内容。": "Einige Ergebnisse werden noch verarbeitet. Verfügbarer Inhalt kann bereits gelesen werden.",
  "Coding Agent 会话": "Coding-Agent-Sitzungen",
  "处理插件实例已停用，请检查配置后重试。": "Diese Verarbeitungs-Plugin-Instanz wurde deaktiviert. Prüfen Sie die Konfiguration, bevor Sie es erneut versuchen.",
  "筛选": "Filter",
  "这些提取门槛与最大等待时间只控制历史资料的窗口处理。已授权且内容就绪的新资料直接进入自动记忆队列，按可用名额持续处理。": "Diese Extraktionsschwellen und die maximale Wartezeit steuern nur historische Verarbeitungsfenster. Neu autorisierte Aufzeichnungen mit bereitem Inhalt gelangen direkt in die automatische Erinnerungswarteschlange und werden je nach verfügbarer Kapazität verarbeitet.",
  "持续整理新资料": "Neue Aufzeichnungen fortlaufend verarbeiten",
  "为新接收的来源资料选择记忆策略。多个策略可共用处理结果；保存设置不会重算历史资料，已有记忆仍保留。": "Wählen Sie Erinnerungsstrategien für neue Quellenaufzeichnungen. Strategien können Verarbeitungsergebnisse teilen; das Speichern verarbeitet ältere Daten nicht neu, und vorhandene Erinnerungen bleiben erhalten.",
  "我的表达或经历": "Meine Äußerungen oder Erlebnisse",
  "第三方内容": "Inhalte von Dritten",
  "混合内容": "Gemischte Inhalte",
  "归属未知": "Zuordnung unbekannt",
  "你对这份资料的声明": "Ihre Erklärung zu dieser Aufzeichnung",
  "你对来源的声明": "Ihre Quellenerklärung",
  "来源提供的上下文": "Von der Quelle gelieferter Kontext",
  "尚无归属声明": "Keine Zuordnungserklärung",
  "内容与我的关系": "Bezug des Inhalts zu mir",
  "归属依据": "Zuordnungsgrundlage",
  "来源声明": "Quellenerklärung",
  "资料声明版本": "Version der Aufzeichnungserklärung",
  "来源内容归属（可选）": "Quellenzuordnung (optional)",
  "纠正内容归属（可选）": "Zuordnung korrigieren (optional)",
  "声明帮助模型区分你的表达、第三方内容和混合引用；归属未知也能查询和整理。": "Erklärungen helfen dem Modell, Ihre Äußerungen, Inhalte von Dritten und gemischte Zitate zu unterscheiden. Eine unbekannte Zuordnung erlaubt weiterhin Abruf und Verarbeitung.",
  "来源声明应用于已有和新资料；单份资料的声明优先。": "Quellenerklärungen gelten für vorhandene und neue Aufzeichnungen; Erklärungen einzelner Aufzeichnungen haben Vorrang.",
  "不声明": "Keine Erklärung",
  "跟随来源": "Quelle folgen",
