  "原文": "Originaltext",
  "自动记忆进度": "Fortschritt der automatischen Erinnerung",
  "按本次新记录接收时选中的配方处理；进度按记录汇总。": "Verwendet die beim Empfang dieser neuen Aufzeichnungen ausgewählten Rezepte; der Fortschritt wird pro Aufzeichnung aggregiert.",
  "完成 {0} / {1} · 处理中 {2} · 等待内容或名额 {3}": "Abgeschlossen {0} / {1} · In Verarbeitung {2} · Warten auf Inhalt oder Kapazität {3}",
  "失败 {0} · 等待模型 {1} · 暂停 {2} · 已取消 {3} · 未启用 {4} · 输入已变更或不可用 {5}": "Fehlgeschlagen {0} · Warten auf Modell {1} · Pausiert {2} · Abgebrochen {3} · Deaktiviert {4} · Eingabe geändert oder nicht verfügbar {5}",
  "工作步骤名额：后台实际 {0}（配置 {1}），交互 {2}，合计 {3}。两条队列独立，不借用名额。": "Kapazität für Arbeitsschritte: Hintergrund effektiv {0} (konfiguriert {1}), interaktiv {2}, gesamt {3}. Die Warteschlangen haben unabhängige Kapazitäten.",
