  "规则配置与应用内容授权分开。修改只形成草稿，返回后保存生效；保存不会开始采集。": "Regelkonfiguration und App-Inhaltsautorisierung sind getrennt. Änderungen bilden einen Entwurf; speichern Sie nach der Rückkehr, um sie anzuwenden. Das Speichern startet die Erfassung nicht.",
