  "这里是生成的格式示例，不读取你的屏幕。实际记录由已授权应用、版本规则和可见内容决定。": "Dies sind erzeugte Formatbeispiele, die Ihren Bildschirm nicht lesen. Tatsächliche Aufzeichnungen hängen von autorisierten Apps, Versionsregeln und sichtbarem Inhalt ab.",
