  "页面采集方式": "Seitenerfassungsmethode",
  "预览当前配置的记录格式": "Aufzeichnungsformate für diese Konfiguration in der Vorschau anzeigen",
  "预览此应用的记录格式": "Aufzeichnungsformate für diese App in der Vorschau anzeigen",
  "高级：查看或编辑全部页面规则": "Erweitert: Alle Seitenregeln anzeigen oder bearbeiten",
  "使用投屏模式（只截图，每次需授权）": "Projektionsmodus verwenden (nur Screenshots; jedes Mal Einwilligung erforderlich)",
  "默认无障碍采集支持页面字段与截图回退。选择投屏会同时改为只截图，锁屏/被杀后必须重新授权。Android 10 截图请选投屏模式。": "Die Bedienungshilfen-Erfassung unterstützt Seitenfelder und Screenshot-Fallback. Die Wahl der Projektion aktiviert ebenfalls „Nur Screenshots“; die Einwilligung muss nach dem Sperren oder Beenden erneuert werden. Verwenden Sie die Projektion für Screenshots unter Android 10.",
  "本周期累计页面 {0} · 截图 {1} · 应用活动 {2} · 媒体 {3} · 笔记 {4} · 已确认 {5}\n拦截 {6} · 失败 {7} · 重试结果 {8}": "Dieser Zeitraum: Seiten {0} · Screenshots {1} · Aktivität {2} · Medien {3} · Notizen {4} · Bestätigt {5}\nBlockiert {6} · Fehlgeschlagen {7} · Wiederholungsergebnisse {8}",
  "本周期累计页面 {0}    截图 {1}    活动 {2}    媒体 {3}    记录 {4}\n本周期已同步 {5} 条": "Dieser Zeitraum: Seiten {0}    Screenshots {1}    Aktivität {2}    Medien {3}    Kurznotizen {4}\nIn diesem Zeitraum synchronisiert: {5}",
  "媒体采集可单独开启，在前台、后台和锁屏时观察播放器公开的状态、应用及曲目/章节信息；不录音、不控制播放。普通通知由单独的通知采集开关控制。使用本机页的开始/暂停控制采集。媒体沿用应用隐私规则、电量限制和同步策略；关闭元数据会同时暂停媒体。": "Beobachtet unabhängig öffentliche Player-Zustände sowie App- und Titel-/Kapitelinformationen im Vordergrund, Hintergrund und Sperrbildschirm. Keine Audioaufzeichnung oder Wiedergabesteuerung. Gewöhnliche Benachrichtigungen haben einen separaten Schalter. Verwenden Sie Start/Pause auf „Gerät“. App-Datenschutz-, Akku- und Synchronisierungsrichtlinien gelten; das Deaktivieren von Metadaten pausiert auch Medien.",
  "日常事件": "Tägliche Ereignisse",
  "截图和页面采集默认组合": "Standards für Screenshot- und Seitenerfassung",
  "截图和页面采集使用独立默认组合；来源覆盖优先。日常事件保留浏览和行动线索，区分计划与完成，并可在对话中按天回顾。": "Screenshots und Seitenerfassungen verwenden eigene Standards; Quellenüberschreibungen haben Vorrang. Tägliche Ereignisse bewahren Surf- und Handlungsspuren, unterscheiden Pläne von Erledigtem und können im Chat tageweise abgerufen werden.",
  "待回答": "Wartet auf Ihre Antwort",
  "稍后处理": "Zurückgestellt",
