  "补充资料对话": "Materialklärung",
  "补充后，仅继续处理这份资料": "Ihre Antwort setzt die Verarbeitung nur für dieses Material fort",
  "打开来源资料": "Quellmaterial öffnen",
  "回答已记录，后续处理状态请查看活动；成果审核完成后才会保存。": "Ihre Antwort wurde aufgezeichnet. Verfolgen Sie die Verarbeitung unter „Aktivität“; Ergebnisse werden nach der Überprüfung gespeichert.",
  "已放到稍后处理，其他工作继续；回来后仍可回答。": "Zurückgestellt, während andere Arbeit weiterläuft. Sie können später zurückkehren und antworten.",
  "已保留资料和不确定性，本次不再追问。": "Material und seine Ungewissheit bleiben erhalten. Für diesen Versuch gibt es keine weiteren Fragen.",
  "来源或处理版本已变化，这个问题不再接受回答。": "Die Quelle oder Verarbeitungsversion hat sich geändert. Diese Frage akzeptiert keine Antworten mehr.",
  "回复补充问题": "Auf die Rückfrage antworten",
  "补充你知道的信息，也可以选择上面的回答。": "Teilen Sie, was Sie wissen, oder wählen Sie oben eine Antwort.",
