  "我有新信息了": "Ich habe neue Informationen",
  "补充问题记录": "Rückfragenverlauf",
  "归属仍然未知，本次评估已结束；原始资料继续保留。": "Die Zuordnung bleibt unbekannt. Diese Bewertung ist beendet; das Originalmaterial bleibt erhalten.",
  "回答已保存到这份资料。相关范围将重新提取并独立复核。": "Ihre Antwort wurde für dieses Material gespeichert. Die betroffenen Bereiche werden erneut extrahiert und unabhängig überprüft.",
