  "同步文件夹、导入文件、记录屏幕或写一条记录。内容会先保存在本机。": "Synchronisieren Sie einen Ordner, importieren Sie eine Datei, zeichnen Sie Ihren Bildschirm auf oder schreiben Sie eine Notiz. Inhalt wird zuerst lokal gespeichert.",
  "中央已收到": "Von Central empfangen",
