  "确认添加内容": "Hinzufügen von Inhalt bestätigen",
  "完整文件会发送到所示中央进行处理；提取正文不代表只上传摘要。未连接时先保存本机任务，首次连接须确认发送范围。": "Die vollständige Datei wird zur Verarbeitung an den angezeigten zentralen Knoten gesendet. Das Extrahieren von Text bedeutet nicht, nur eine Zusammenfassung hochzuladen. Speichern Sie die Aufgabe bei getrennter Verbindung lokal; bestätigen Sie den Sendebereich bei der ersten Verbindung.",
