  "这是生成的格式示意，不读取你的屏幕。仅应用活动不读取屏幕或正文；完整内容保存经过遮挡的截图或获准页面。": "Dieses erzeugte Formatbeispiel liest Ihren Bildschirm nicht. App-Aktivität liest weder Bildschirme noch Text; vollständiger Inhalt speichert maskierte Screenshots oder autorisierte Seiten.",
