  "控制自动提取与整合；原件、已有记忆与只读查询保留。独立回顾按自己的设置运行。": "Steuert automatische Extraktion und Integration. Originale, vorhandene Erinnerungen und schreibgeschützte Abfragen bleiben verfügbar. Persönliche Rückblicke folgen ihren eigenen Einstellungen.",
