  "当前准入代次 {0} · 绑定代次 {1}": "Zulassungsgeneration {0} · Bindungsgeneration {1}",
  "暂停期间的新资料只归档。恢复只处理新资料，不会自动补跑暂停期间的历史。": "Neue Daten werden während einer Pause nur archiviert. Das Fortsetzen verarbeitet nur neue Daten; pausierte ältere Daten werden nicht automatisch nachgeholt.",
  "已停止新增自动任务；已授权任务保留原范围与代次，完成后停用。": "Die Zulassung neuer automatischer Aufgaben wurde gestoppt. Zuvor autorisierte Aufgaben behalten ihren ursprünglichen Bereich und ihre Generation und werden vor der Deaktivierung abgearbeitet.",
  "外部结果尚未确认，停止请求不代表远端工作已结束。": "Externe Ergebnisse bleiben unbestätigt. Eine Stoppanfrage beweist nicht, dass die Remote-Arbeit beendet ist.",
  "立即停止": "Sofort stoppen",
