  "模块组合": "Modulkombination",
  "当前": "Aktuell",
  "准备与生效分开执行。只有范围、正文与索引核验通过后，才能切换写入与查询绑定。": "Vorbereitung und Aktivierung sind getrennt. Schreib- und Abfragebindungen können erst geändert werden, nachdem Bereich, Inhalt und Indizes verifiziert wurden.",
  "预览更换": "Ersetzungsvorschau",
