  "分析能力技术详情": "Technische Details zu Analysefähigkeiten",
  "覆盖原因：": "Abdeckungsgrund:",
  "该录音来源当前未注册。请重新选择可用来源；已归档资料仍可从资料库查看。": "Dieser Aufnahmeanbieter ist derzeit nicht registriert. Wählen Sie einen verfügbaren Anbieter; bereits archiviertes Material bleibt in der Bibliothek zugänglich.",
  "高级：当前注册的分析能力": "Erweitert: registrierte Analysefähigkeiten",
