  "还没有收到 Coding 来源。按上方客户端步骤接入后，可在这里查看接收与处理结果。": "Es wurde noch keine Coding-Quelle empfangen. Folgen Sie oben den Schritten für den nativen Client und kehren Sie dann hierher zurück, um Empfänge und Verarbeitungsergebnisse anzuzeigen.",
  "后台模型与工具执行并发（Harness）": "Parallelität der Hintergrund-Modell- und Werkzeugausführung (Harness)",
