  "检查 / 分配对应模块 →": "Das zugehörige Modul prüfen oder zuweisen →",
  "检查模型连接": "Modellverbindungen prüfen",
  "检查模型连接 →": "Modellverbindungen prüfen →",
  "接收成功或任务完成不代表源会话内容完整；请在会话正文中另行核对覆盖范围和缺片提示。": "Ein Empfang oder eine abgeschlossene Aufgabe beweist nicht, dass die Quellunterhaltung vollständig ist. Prüfen Sie Abdeckung und Hinweise auf fehlende Teile im veröffentlichten Text.",
  "接收状态暂不可用，请展开重试。": "Empfangsstatus nicht verfügbar. Zum Wiederholen aufklappen.",
  "仅保留引用": "Nur Referenz",
  "具体原因暂时无法读取。": "Der konkrete Grund kann derzeit nicht gelesen werden.",
  "开始使用 AI 功能": "Mit KI-Funktionen beginnen",
  "可继续查看下方补充问题或相关资料。具体步骤与未读取部分在「技术详情」中核对。": "Prüfen Sie unten Klärungsfragen oder zugehöriges Material. Konkrete Schritte und ungelesene Aufzeichnungen finden Sie unter „Technische Details“.",
  "来源 ID：": "Quellen-ID:",
  "来源正文": "Quellen-Volltext",
  "类型：": "Typ:",
  "例如问答检查「Chat 问答」，记忆提取检查「Memory 记忆提取」。无需创建新预设或修改所有模块；高级参数和自动处理节奏按需设置。": "Prüfen Sie beispielsweise „Chat-Q&A“ für Fragen und „Erinnerungsextraktion“ für das Extrahieren von Erinnerungen. Sie müssen kein neues Profil erstellen oder alle Module ändern; passen Sie erweiterte Parameter und den Rhythmus der automatischen Verarbeitung bei Bedarf an.",
  "连接到中央 →": "Mit dem zentralen Knoten verbinden →",
  "录音数据源": "Aufnahmedatenquellen",
  "录音与转写": "Aufnahmen und Transkripte",
  "模型连接尚未配置": "Modellverbindung ist nicht konfiguriert",
  "模型连接设置": "Modellverbindungseinstellungen",
  "模型文件已安装": "Modelldateien sind installiert",
  "目前还没有明确的处理原因。": "Es ist noch kein konkreter Verarbeitungsgrund verfügbar.",
  "内容不完整": "Unvollständiger Inhalt",
  "排队等待": "Wartet in der Warteschlange",
