  "资料变化，待重新核对": "Material geändert; erneute Prüfung erforderlich",
  "资料范围尚不完整或仍在整理。请核对已有正文；缺失部分不能作为已经读取的证据。": "Die Materialabdeckung ist unvollständig oder wird noch verarbeitet. Prüfen Sie den verfügbaren Text; fehlende Teile können nicht als bereits gelesene Nachweise gelten.",
  "资料来源": "Materialquelle",
