  "仅显示本机保留的最近上传结果；中央接收不代表已完成处理。": "Zeigt die letzten auf diesem Gerät aufbewahrten Upload-Ergebnisse. Der Empfang durch Central bedeutet nicht, dass die Verarbeitung abgeschlossen ist.",
  "删除中央保存的这份文件。不会删除设备上的原件，也不会改变来源同步策略。删除后无法恢复。": "Diese in Central gespeicherte Datei löschen. Originale auf Ihren Geräten und die Quellsynchronisierungsrichtlinie bleiben unverändert. Dies kann nicht rückgängig gemacht werden.",
