  "恢复接入仅允许接收资料；录音同步需在录音同步设置中确认范围并启用。": "Das Fortsetzen der Aufnahme erlaubt dieser Quelle nur, Material zu empfangen. Bestätigen Sie den Umfang und aktivieren Sie die Aufnahmesynchronisierung in den Aufnahmesynchronisierungseinstellungen.",
  "录音同步设置": "Aufnahmesynchronisierungseinstellungen",
  "已保存账号绑定不代表当前登录或读取权限有效。“重新检测”检查中央运行环境；请结合授权结果与同步步骤确认账号权限。": "Eine gespeicherte Kontoverknüpfung bestätigt keine gültige Anmeldung oder Leseberechtigungen. „Erneut prüfen“ untersucht die zentrale Laufzeitumgebung; bestätigen Sie Kontoberechtigungen anhand von Autorisierungsergebnissen und Synchronisierungsschritten.",
  "结构化内容未采集：请先配置允许的 Chrome 站点；应用时长按所选设置记录": "Strukturierte Inhalte nicht erfasst: Konfigurieren Sie zuerst erlaubte Chrome-Websites; die App-Dauer folgt Ihrer Auswahl",
  "结构化内容未采集：Mote Chrome 扩展尚未连接；应用时长按所选设置记录": "Strukturierte Inhalte nicht erfasst: Die Mote-Chrome-Erweiterung ist nicht verbunden; die App-Dauer folgt Ihrer Auswahl",
  "结构化内容未采集：Chrome 窗口、站点授权或遮挡校验未通过；应用时长按所选设置记录": "Strukturierte Inhalte nicht erfasst: Chrome-Fenster-, Website-Berechtigungs- oder Sichtbarkeitsprüfungen fehlgeschlagen; die App-Dauer folgt Ihrer Auswahl",
  "切换语言会重新加载页面，请先保存未提交的修改。继续？": "Beim Wechseln der Sprache wird die Seite neu geladen. Speichern Sie zuerst ausstehende Änderungen. Fortfahren?",
  "无法保存语言偏好，请检查浏览器存储。": "Die Spracheinstellung konnte nicht gespeichert werden. Prüfen Sie den Browser-Speicher.",
  "切换语言会重新加载界面，请先保存未提交的设置。继续？": "Beim Wechseln der Sprache wird dieses Fenster neu geladen. Speichern Sie zuerst ausstehende Einstellungen. Fortfahren?",
  "语言保存失败，请重试。": "Die Sprache konnte nicht gespeichert werden. Bitte versuchen Sie es erneut.",
