  "请求头包含 X-Mote-Delivery-Id、X-Mote-Event、X-Mote-Timestamp 与 X-Mote-Signature。签名值为 sha256=HMAC(secret, timestamp.deliveryId.body)。": "Headers include X-Mote-Delivery-Id, X-Mote-Event, X-Mote-Timestamp and X-Mote-Signature. The signature is sha256=HMAC(secret, timestamp.deliveryId.body).",
  "轮换密钥": "Rotate secret",
