  "正在录音 · 点击结束": "Recording · click to end",
  "正在录音": "Recording",
  "正在检查权限": "Checking permissions",
  "正在结束本机会议录音": "Ending local meeting recording",
  "系统音频": "System audio",
  "系统音频不可用": "System audio is unavailable",
  "系统音频授权已结束，会议录音没有继续。": "System-audio authorization ended, so the meeting recording did not continue.",
  "系统音频授权无效": "System-audio authorization is invalid",
  "系统音频权限未授予，会议录音没有开始。请允许屏幕与系统音频录制后重试；不会在缺少系统声时只录麦克风。": "System-audio permission was not granted, so the meeting recording did not start. Allow screen and system-audio recording and retry; Mote will not silently record the microphone alone.",
  "系统音频权限未授予，会议录音没有开始；不会在缺少系统声时只录麦克风。": "System-audio permission was not granted, so the meeting recording did not start; Mote will not silently record the microphone alone.",
  "系统音频读取失败": "Reading system audio failed",
  "结束并入库": "End and archive",
  "请确认已告知在场的人并得到同意。该确认只在本机记住一次；之后开始会议录音不再重复询问。取消则不会开始录音。": "Confirm that everyone present has been told and agrees. This confirmation is remembered once on this device; later meeting recordings do not ask again. Cancel does not start recording.",
  "请重试": "Try again",
  "这场会议将同时录制麦克风与系统音频，结束后上传到你的中央并转写。": "This meeting will record the microphone and system audio together, then upload to your Central for transcription when you end it.",
  "这场会议将同时录制麦克风与系统音频，结束后上传到你的中央并转写。请确认已告知在场的人并得到同意。该确认只在本机记住一次；取消则不会开始录音。": "This meeting will record the microphone and system audio together, then upload to your Central for transcription when you end it. Confirm that everyone present has been told and agrees. This confirmation is remembered once on this device; cancel does not start recording.",
  "这场会议录音已经结束。": "This meeting recording has already ended.",
  "麦克风": "Microphone",
  "麦克风不可用": "Microphone is unavailable",
  "麦克风与系统音频 · 由你结束": "Microphone and system audio · you end it",
  "麦克风与系统音频同时采集；缺少任一项权限时不会开始，也不会静默只录麦克风。第一次开始时先请告知在场的人，该确认只在本机记住一次。结束后音频进入中央已有文件转写，不会与飞书妙记、钉钉闪记或记录页的语音附件合并。": "The microphone and system audio are captured together. If either permission is missing, recording does not start and Mote never silently records only the microphone. First tell everyone present; that confirmation is remembered once on this device. When you end it, the audio enters Central's existing file transcription and is not merged with audio from the recording page or Feishu/DingTalk recordings.",
  "麦克风与系统音频已允许": "Microphone and system audio allowed",
  "麦克风与系统音频权限 ↗": "Microphone and system-audio permissions ↗",
  "麦克风与系统音频权限": "Microphone and system-audio permissions",
  "麦克风与系统音频权限将在开始时检查；缺少任一项都不会开始。": "Microphone and system-audio permissions are checked at start; if either is missing, recording does not start.",
  "麦克风权限未授予，会议录音不会开始。": "Microphone permission was not granted, so the meeting recording will not start.",
  "麦克风权限未授予，会议录音没有开始。": "Microphone permission was not granted, so the meeting recording did not start.",
  "麦克风权限未授予，会议录音没有开始。请在系统设置中允许麦克风后重试。": "Microphone permission was not granted, so the meeting recording did not start. Allow the microphone in System Settings and retry.",
  "麦克风缓冲不可用": "Microphone buffer is unavailable",
  "麦克风读取失败": "Reading the microphone failed",
  "日志占用 {0} / {1}": "Protokollspeicher: {0} / {1}",
  "容量不足时优先清理详细记录，保留时间以实际覆盖范围为准。": "Bei Platzmangel werden zuerst detaillierte Aufzeichnungen gelöscht. Maßgeblich ist der tatsächlich verfügbare Zeitraum.",
  "级别": "Stufe",
  "占用空间": "Belegter Speicher",
