  "原件能力": "Zugriff auf das Original",
  "可打开原件": "Original kann geöffnet werden",
  "正文提取": "Textextraktion",
  "来源最近一次观察时间不代表设备当前在线。提取、语义理解、向量索引和原件打开分别确认。": "Die letzte Quellenbeobachtung bedeutet nicht, dass das Gerät jetzt online ist. Extraktion, semantische Verarbeitung, Vektorindexierung und Zugriff auf das Original werden separat bestätigt.",
  "快照原件未保留；已提取正文仍按当前覆盖和读取权限提供。": "Das Snapshot-Original wird nicht aufbewahrt. Extrahierter Text bleibt entsprechend der aktuellen Abdeckung und Leseberechtigung verfügbar.",
  "内容提取或生成摘要不代表已完成全文语义理解。": "Die Extraktion von Inhalten oder die Erstellung einer Zusammenfassung belegt kein vollständiges semantisches Verständnis der Datei.",
  "向量索引尚未完整就绪；可用正文仍可通过文本检索查找。": "Der Vektorindex ist noch nicht vollständig bereit. Verfügbarer Text kann weiterhin per Textsuche gefunden werden.",
  "问文件": "Zu dieser Datei fragen",
  "请基于这份文件拟定可编辑的工作草稿，说明目标和资料范围，等我确认后开始。": "Erstelle einen bearbeitbaren Arbeitsentwurf auf Grundlage dieser Datei. Nenne Ziel und Materialumfang und warte vor dem Start auf meine Bestätigung.",
  "用于事项": "Für ein Vorhaben verwenden",
  "用于事项会先准备可编辑草稿，点击开始后才执行。": "Zuerst wird ein bearbeitbarer Entwurf vorbereitet. Die Arbeit beginnt erst nach einem Klick auf Starten.",
  "保存方式只提交当前选择，不更改其他来源设置。已有文件的实际能力以文件状态为准。": "Beim Speichern wird nur die gewählte Aufbewahrungsart übermittelt. Andere Quelleneinstellungen bleiben unverändert. Die tatsächlichen Möglichkeiten vorhandener Dateien stehen im Dateistatus.",
