  "可以离开或刷新，中央会继续执行。": "Du kannst die Seite verlassen oder aktualisieren; Central führt die Arbeit fort.",
  "多对话已关闭。可在对话设置中开启。": "Mehrere Unterhaltungen sind aus. Aktiviere sie in den Unterhaltungseinstellungen.",
  "对话设置": "Unterhaltungseinstellungen",
