  "尚未读取主对话，请刷新后重试。": "Die Hauptunterhaltung ist noch nicht geladen. Aktualisiere und versuche es erneut.",
  "已加载最近 {0} 轮；更早的对话仍在中央。": "Die letzten {0} Runden sind geladen; ältere Unterhaltung bleibt in Central.",
  "已接收": "Angenommen",
  "已显示这段对话的 {0} 轮。": "Alle {0} Runden dieser Unterhaltung werden angezeigt.",
  "开启后可以新建独立对话。关闭后历史仍可查看，默认提问回到主对话。": "Ermöglicht neue eigenständige Unterhaltungen. Beim Ausschalten bleibt der Verlauf lesbar und gewöhnliche Fragen gehen an die Hauptunterhaltung.",
  "指定模型窗口": "Modellfenster angeben",
  "指定模型窗口需要填写正整数。": "Ein angegebenes Modellfenster muss eine positive Ganzzahl sein.",
  "排队等待回答": "Wartet auf Antwort",
  "服务端按当前模型窗口和完整请求预算计算历史目标；这里只保存比例与窗口偏好，不在浏览器中估算。": "Der Server berechnet das Verlaufsziel aus dem aktuellen Modellfenster und dem vollständigen Anforderungsbudget. Dieses Formular speichert nur Verhältnis- und Fenstereinstellungen; der Browser schätzt sie nicht.",
  "未命名对话": "Unbenannte Unterhaltung",
  "模型窗口": "Modellfenster",
  "消息已保存在中央，等待开始回答。": "Die Nachricht ist in Central gespeichert und wartet auf den Start.",
  "窗口大小（tokens）": "Fenstergröße (Tokens)",
  "缺少可信能力信息时使用保守窗口。历史目标是比例与请求预算的较小值，由服务端在每次请求时计算。": "Fehlen verlässliche Fähigkeitsangaben, wird ein konservatives Fenster verwendet. Das Verlaufsziel ist der kleinere Wert aus Verhältnis und Anforderungsbudget und wird vom Server pro Anfrage berechnet.",
  "设为主对话": "Als Hauptunterhaltung festlegen",
  "设置尚未读取完成，请稍后重试。": "Die Einstellungen sind noch nicht geladen. Versuche es gleich erneut.",
  "这条回答已取消，晚到的结果不会写回。": "Diese Antwort wurde abgebrochen; ein verspätetes Ergebnis wird nicht zurückgeschrieben.",
  "默认打开主对话。多个对话默认关闭；关闭不会删除已有对话。": "Ask öffnet standardmäßig die Hauptunterhaltung. Mehrere Unterhaltungen sind standardmäßig aus; Ausschalten löscht keine bestehenden Unterhaltungen.",
  "记忆浏览": "Erinnerungen durchsuchen",
