  "按已关联的记忆身份浏览；同名人物分别保留。": "Nach verknüpften Erinnerungsidentitäten durchsuchen. Namensgleiche Personen bleiben getrennt.",
  "本页暂无已关联的人物。可继续浏览记忆或主题。": "Keine verknüpften Personen auf dieser Seite. Erinnerungen und Themen können weiterhin durchsucht werden.",
