  "初次认识": "Erstes Kennenlernen",
  "开始初次认识": "Erstes Kennenlernen starten",
  "取消初次认识": "Erstes Kennenlernen abbrechen",
  "继续初次认识": "Erstes Kennenlernen fortsetzen",
  "连接能带来什么": "Was eine Verbindung ermöglicht",
  "连接成功后，Mote 可以先从你选的一小部分资料开始认识你。": "Nach dem Verbinden kann Mote dich anhand einer kleinen Auswahl von Materialien kennenlernen.",
  "把文件和记录变成可查的资料库": "Dateien und Notizen in eine durchsuchbare Bibliothek verwandeln",
  "记住人物、事项和承诺，回答时引用原文": "Personen, Anliegen und Zusagen merken und in Antworten Originale zitieren",
  "发现最近在忙什么，并给出下一步": "Erkennen, woran du zuletzt gearbeitet hast, und einen nächsten Schritt vorschlagen",
  "新资料到达后更新相关事项，而不是只多一个文件": "Bei neuen Materialien zugehörige Anliegen aktualisieren, statt nur eine weitere Datei hinzuzufügen",
  "连接成功只表示可以同步，不代表全库已经理解。": "Eine erfolgreiche Verbindung bedeutet nur, dass die Synchronisierung verfügbar ist; sie bedeutet nicht, dass die gesamte Bibliothek verstanden wurde.",
  "这里只决定本次初次认识读取哪些已同步资料，不改变来源授权或保存方式。": "Dies wählt nur aus, welche synchronisierten Materialien dieses erste Kennenlernen liest; es ändert weder Quellenfreigabe noch Aufbewahrung.",
  "同步、正文提取和语义理解分别计算；连接或提取完成不等于语义理解完成。": "Synchronisierung, Textextraktion und semantisches Verständnis werden getrennt gezählt; eine abgeschlossene Verbindung oder Extraktion bedeutet nicht, dass das semantische Verständnis abgeschlossen ist.",
  "初次认识暂不可用，仍可继续使用已同步的资料。": "Das erste Kennenlernen ist nicht verfügbar; synchronisierte Materialien bleiben nutzbar.",
  "一次最多选择 100 份资料。": "Wähle höchstens 100 Materialien auf einmal aus.",
  "本次仅处理已选的 {0} 份资料。": "Diesmal werden nur die {0} ausgewählten Materialien verarbeitet.",
  "有新资料到达，可选择后再次开始初次认识。": "Neue Materialien sind eingetroffen; wähle sie aus und starte das erste Kennenlernen erneut.",
  "仅保存引用，未导入正文": "Nur Referenz; kein Text importiert",
  "正文不可用，暂不能用于初次认识": "Der Text ist nicht verfügbar; dieses Material kann noch nicht verwendet werden.",
  "原文提取未完成，请查看来源与处理状态。": "Die Extraktion des Originaltexts ist nicht abgeschlossen; prüfe Quelle und Verarbeitungsstatus.",
  "理解没有完成，请检查模型与服务后重试。": "Das Verständnis wurde nicht abgeschlossen; prüfe Modell und Dienste und versuche es erneut.",
  "这次选择的资料超过单次处理上限，请减少选择后重试。": "Die ausgewählten Materialien überschreiten das Limit für einen Lauf; wähle weniger aus und versuche es erneut.",
  "取消后已完成的结果会保留；继续只会处理未完成的资料。": "Ein Abbruch behält abgeschlossene Ergebnisse; beim Fortsetzen werden nur unfertige Materialien verarbeitet.",
  "本次选择的资料已完成；其他资料未包含。": "Die für diesen Lauf ausgewählten Materialien sind abgeschlossen; andere Materialien sind nicht enthalten.",
  "本次资料": "Materialien dieses Laufs",
  "初次认识由你手动开始，仍会使用当前模型配置。": "Das erste Kennenlernen startest du manuell; es verwendet weiterhin die aktuelle Modellkonfiguration.",
  "初次认识仍只处理你选择的资料。": "Das erste Kennenlernen verarbeitet weiterhin nur die von dir ausgewählten Materialien.",
  "保存方式沿用来源设置；需要更改时打开该来源的「连接与范围」。": "Die Aufbewahrung folgt der Einstellung der jeweiligen Quelle; öffne „Verbindung und Umfang“ dieser Quelle, um sie zu ändern.",
  "所选资料当前不可读取，请检查来源授权后重新选择。": "Die ausgewählten Materialien sind derzeit nicht lesbar; prüfe die Quellenfreigabe und wähle erneut.",
  "部分 {0}/{1}": "Teilweise {0}/{1}",
  "原件状态暂不可确认；正文仍可读取。": "Die Verfügbarkeit des Originals ist derzeit nicht bestätigt; der Text bleibt lesbar.",
  "初次认识已同步资料": "Synchronisierte Materialien kennenlernen",
  "只处理你勾选的已同步资料；不会重新上传本机文件，也不会自动扩大来源范围。": "Nur ausgewählte synchronisierte Materialien werden verarbeitet. Lokale Dateien werden nicht erneut hochgeladen und der Quellenbereich wird nie automatisch erweitert.",
  "初次认识会使用你已连接的模型处理所选资料。": "Beim Kennenlernen werden die ausgewählten Materialien an das verbundene Modell gesendet.",
