  "摘要、语义分组、复核、Memory 与 Ask 继续使用各自所选模型。": "Zusammenfassungen, semantische Gruppierung, Überprüfung, Memory und Ask verwenden weiterhin ihre jeweils ausgewählten Modelle.",
  "保守消重仅影响派生稿；原文始终可对照和导出。": "Die vorsichtige Deduplizierung betrifft nur das abgeleitete Transkript; das Original bleibt zum Vergleich und Export verfügbar.",
