  "首次同步建立基线，之后接入新增内容并跟踪已接入资料的修订。": "Die erste Synchronisierung legt einen Ausgangsstand fest. Danach werden neue Inhalte erfasst und Änderungen bereits erfasster Materialien nachverfolgt.",
  "可安全推进的解析会自动保存；关键缺口需要确认。": "Ergebnisse, bei denen sicher fortgefahren werden kann, werden automatisch gespeichert; wesentliche Lücken erfordern eine Bestätigung.",
